    'settings_skills_title': { 'English': 'Agent skills', 'Mandarin': 'Agent 技能', 'Japanese': 'エージェントのスキル', 'Malay': 'Kemahiran ejen' },
    'settings_skills_detail': { 'English': 'Skills are short written instructions the AI agent can load when a task matches, for example how to choose a metric or how your team writes summaries. They only guide the analysis; they never change your data or the app safety rules.', 'Mandarin': '技能是 AI agent 在任务匹配时可以读取的简短文字说明，例如如何选择指标，或你的团队如何撰写摘要。它们只指导分析，不会修改你的数据，也不会改变应用的安全规则。', 'Japanese': 'スキルは、タスクに合うときに AI エージェントが読み込む短い手順書です（指標の選び方、チームの要約の書き方など）。分析を導くだけで、データやアプリの安全ルールは変更しません。', 'Malay': 'Kemahiran ialah arahan bertulis ringkas yang boleh dimuatkan oleh ejen AI apabila tugas sepadan, contohnya cara memilih metrik atau cara pasukan anda menulis ringkasan. Ia hanya membimbing analisis dan tidak mengubah data anda atau peraturan keselamatan aplikasi.' },
    'settings_skills_import': { 'English': 'Add skill files (.md)', 'Mandarin': '添加技能文件 (.md)', 'Japanese': 'スキルファイルを追加 (.md)', 'Malay': 'Tambah fail kemahiran (.md)' },
