    'settings_skills_edit_hint': { 'English': 'Saving a built-in skill keeps your version; Restore default brings the original back.', 'Mandarin': '保存内置技能会保留你的版本；“恢复默认”可还原原版。', 'Japanese': '組み込みスキルを保存すると自分のバージョンが残ります。「既定に戻す」で元に戻せます。', 'Malay': 'Menyimpan kemahiran terbina dalam akan mengekalkan versi anda; Pulihkan lalai mengembalikan yang asal.' },
    'settings_skills_format_title': { 'English': 'Skill file format', 'Mandarin': '技能文件格式', 'Japanese': 'スキルファイルの形式', 'Malay': 'Format fail kemahiran' },
    'settings_skills_format_hint': { 'English': 'A skill is a markdown file that starts with a name (lowercase letters, digits and hyphens) and a description that says when to use it. A skill with the same name as a built-in one replaces it.', 'Mandarin': '技能是一个 markdown 文件，开头需要名称（小写字母、数字和连字符）以及说明何时使用的描述。与内置技能同名的技能会替换内置技能。', 'Japanese': 'スキルは、名前（小文字・数字・ハイフン）と、いつ使うかを説明する description で始まる markdown ファイルです。組み込みと同じ名前のスキルは置き換えます。', 'Malay': 'Kemahiran ialah fail markdown yang bermula dengan nama (huruf kecil, nombor dan sempang) dan huraian bila hendak menggunakannya. Kemahiran dengan nama yang sama seperti kemahiran terbina dalam akan menggantikannya.' },
